using Microsoft.EntityFrameworkCore;
using System.Text.Json;
namespace Society.Api;
public static partial class FinanceEndpoints {
 static void MapAccounting(RouteGroupBuilder t){
 t.MapGet("/journals",async(Guid tenant,Guid? entity,Guid? workspace,DateOnly? from,DateOnly? to,int? page,AppDb db,FinanceService s)=>{var q=s.Scoped<JournalEntry>(tenant,entity:entity,workspace:workspace).Where(j=>j.Posted);if(from!=null)q=q.Where(j=>j.Date>=from);if(to!=null)q=q.Where(j=>j.Date<=to);return Results.Ok(new{total=await q.CountAsync(),items=await q.OrderByDescending(j=>j.Date).ThenByDescending(j=>j.Id).Skip(Page(page)*50).Take(50).Select(j=>new{j.Id,j.Number,j.Date,j.Currency,j.Purpose,j.SourceKind,j.SourceId,j.Posted,j.ReversesId,j.AuthorId,j.ApprovedBy,debit=db.Set<JournalLine>().Where(l=>l.JournalId==j.Id).Sum(l=>l.Debit),credit=db.Set<JournalLine>().Where(l=>l.JournalId==j.Id).Sum(l=>l.Credit)}).ToListAsync()});});
 t.MapGet("/journals/{id:guid}",async(Guid tenant,Guid id,AppDb db,FinanceService s)=>{var j=await db.Set<JournalEntry>().AsNoTracking().SingleOrDefaultAsync(j=>j.TenantId==tenant&&j.Id==id)??throw new AccessDeniedException();await s.Require(tenant,j.EntityId,j.UnitId);return Results.Ok(new{journal=j,lines=await (from l in db.Set<JournalLine>() join a in db.Set<LedgerAccount>() on l.AccountId equals a.Id where l.JournalId==id&&l.TenantId==tenant select new{l.Id,a.Code,a.Name,l.Debit,l.Credit,l.Memo,l.MembershipId,l.CounterpartyUnitId}).ToListAsync()});});
 t.MapPost("/journals",async(Guid tenant,ManualJournalWrite r,AppDb db,Access a,FinanceService s)=>{await s.Require(tenant,r.EntityId,r.UnitId,"finance.post");await using var tx=await db.Database.BeginTransactionAsync();await FinanceService.Lock(db,tenant);if(r.Key.Length is <3 or >100||r.Purpose.Length is <3 or >1000||r.Lines.Length is <2 or >100||r.Lines.Sum(l=>l.Debit)!=r.Lines.Sum(l=>l.Credit)||r.Lines.Sum(l=>l.Debit)<=0)throw new DomainException("Enter a balanced journal and stable request key");var codes=r.Lines.Select(l=>l.AccountCode).ToArray();if(await db.Set<LedgerAccount>().AnyAsync(x=>x.TenantId==tenant&&x.EntityId==r.EntityId&&codes.Contains(x.Code)&&x.Control))throw new DomainException("Control accounts require source-document posting through invoice/payment/settlement workflows");var old=await db.Set<FinanceJob>().SingleOrDefaultAsync(j=>j.TenantId==tenant&&j.EntityId==r.EntityId&&j.Key=="journal:"+r.Key);if(old!=null)return Results.Ok(old);var job=new FinanceJob{TenantId=tenant,EntityId=r.EntityId,UnitId=r.UnitId,Kind="ManualJournal",AuthorId=a.UserId,State="Pending Approval",Key="journal:"+r.Key,Payload=JsonSerializer.Serialize(r)};db.Add(job);a.Audit(tenant,"finance.journal.requested",job.Id);await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(job);});
 t.MapPost("/journals/requests/{id:guid}/decision",async(Guid tenant,Guid id,FinanceDecision r,AppDb db,Access a,FinanceService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await FinanceService.Lock(db,tenant);var job=await db.Set<FinanceJob>().SingleOrDefaultAsync(j=>j.TenantId==tenant&&j.Id==id&&j.Kind=="ManualJournal"&&j.State=="Pending Approval")??throw new AccessDeniedException();var e=await s.Require(tenant,job.EntityId,job.UnitId,"finance.post");var input=JsonSerializer.Deserialize<ManualJournalWrite>(job.Payload)!;await s.Review(tenant,id,job.AuthorId,job.UnitId!.Value,"FinanceJournal",r,input.Lines.Sum(l=>l.Debit),e);if(r.Decision=="Approve"){var j=await s.Post(e,job.UnitId.Value,input.Date,input.Purpose,"Manual",job.Id,"manual:"+job.Id,input.Lines,job.AuthorId,a.UserId);job.State="Posted";job.DocumentId=j.Id;}else job.State="Rejected";await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(job);});
 t.MapPost("/journals/{id:guid}/reverse",async(Guid tenant,Guid id,ReverseWrite r,AppDb db,Access a,FinanceService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await FinanceService.Lock(db,tenant);var j=await db.Set<JournalEntry>().SingleOrDefaultAsync(j=>j.TenantId==tenant&&j.Id==id&&j.Posted)??throw new AccessDeniedException();var e=await s.Require(tenant,j.EntityId,j.UnitId,"finance.post");if(j.SourceKind!="Manual")throw new DomainException("Reverse source journals through credit, refund or settlement workflows");if(j.AuthorId==a.UserId||r.Reason.Length is <3 or >1000)throw new AccessDeniedException();await a.Require(tenant,"finance.approve",j.UnitId);var rows=await (from l in db.Set<JournalLine>() join account in db.Set<LedgerAccount>() on l.AccountId equals account.Id where l.JournalId==id select new JournalInput(account.Code,l.Credit,l.Debit,r.Reason)).ToArrayAsync();var reversed=await s.Post(e,j.UnitId!.Value,r.Date,r.Reason,"Reversal",id,"reversal:"+id,rows,a.UserId,a.UserId,reverse:id);await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(reversed);});
 t.MapPost("/inter-entity",async(Guid tenant,InterEntityObligation r,AppDb db,Access a,FinanceService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await FinanceService.Lock(db,tenant);var from=await s.Require(tenant,r.EntityId,r.UnitId,"finance.interentity");var to=await s.Require(tenant,r.OtherEntityId,r.OtherUnitId,"finance.interentity");FinanceService.Money(r.Amount,from.Currency);if(from.Id==to.Id||from.Currency!=to.Currency||r.Purpose.Length is <3 or >1000)throw new DomainException("Inter-entity obligations need separate entities, one shared currency and a purpose");var x=new InterEntityObligation{TenantId=tenant,EntityId=from.Id,UnitId=r.UnitId,OtherEntityId=to.Id,OtherUnitId=r.OtherUnitId,Amount=r.Amount,Currency=from.Currency,Purpose=r.Purpose,Date=r.Date,AuthorId=a.UserId};db.Add(x);a.Audit(tenant,"finance.interentity.requested",x.Id);await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(x);});
 t.MapGet("/inter-entity",async(Guid tenant,Guid? entity,FinanceService s)=>await s.Scoped<InterEntityObligation>(tenant,entity:entity).OrderByDescending(x=>x.Date).Take(200).ToListAsync());
 t.MapPost("/inter-entity/{id:guid}/decision",async(Guid tenant,Guid id,FinanceDecision r,AppDb db,Access a,FinanceService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await FinanceService.Lock(db,tenant);var x=await db.Set<InterEntityObligation>().SingleOrDefaultAsync(x=>x.TenantId==tenant&&x.Id==id&&x.Status=="Pending Approval")??throw new AccessDeniedException();var from=await s.Require(tenant,x.EntityId,x.UnitId,"finance.interentity");var to=await s.Require(tenant,x.OtherEntityId,x.OtherUnitId,"finance.interentity");await a.Require(tenant,"finance.approve",x.OtherUnitId);await s.Review(tenant,id,x.AuthorId,x.UnitId!.Value,"FinanceInterEntity",r,x.Amount,from);if(r.Decision=="Approve"){var j=await s.Post(from,x.UnitId.Value,x.Date,x.Purpose,"InterEntityAllocation",id,"interentity:"+id,[new("3000",x.Amount,0),new("2400",0,x.Amount)],x.AuthorId,a.UserId);var other=await s.Post(to,x.OtherUnitId,x.Date,x.Purpose,"InterEntityAllocation",id,"interentity-receivable:"+id,[new("1200",x.Amount,0),new("3000",0,x.Amount)],x.AuthorId,a.UserId);x.JournalId=j.Id;x.OtherJournalId=other.Id;x.Status="Approved";x.ApprovedBy=a.UserId;}else x.Status="Rejected";await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(x);});
 t.MapPost("/inter-entity/{id:guid}/settlements",async(Guid tenant,Guid id,SettlementWrite r,AppDb db,Access a,FinanceService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await FinanceService.Lock(db,tenant);var x=await db.Set<InterEntityObligation>().SingleOrDefaultAsync(x=>x.TenantId==tenant&&x.Id==id&&x.Status=="Approved")??throw new AccessDeniedException();var e=await s.Require(tenant,x.EntityId,x.UnitId,"finance.interentity");await s.Require(tenant,x.OtherEntityId,x.OtherUnitId,"finance.interentity");FinanceService.Money(r.Amount,e.Currency);var pending=await db.Set<InterEntitySettlement>().Where(y=>y.ObligationId==id&&y.Status=="Pending Confirmation").SumAsync(y=>y.Amount);if(r.Amount>x.Amount-x.Settled-pending||r.Reference.Length is <3 or >160)throw new DomainException("Check remaining obligation and bank evidence reference");var settlement=new InterEntitySettlement{TenantId=tenant,EntityId=x.EntityId,UnitId=x.UnitId,ObligationId=id,Amount=r.Amount,Reference=r.Reference,Date=r.Date,AuthorId=a.UserId};db.Add(settlement);await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(settlement);});
 t.MapGet("/settlements",async(Guid tenant,Guid? entity,FinanceService s)=>await s.Scoped<InterEntitySettlement>(tenant,entity:entity).OrderByDescending(x=>x.Date).Take(200).ToListAsync());
 t.MapPost("/settlements/{id:guid}/decision",async(Guid tenant,Guid id,FinanceDecision r,AppDb db,Access a,FinanceService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await FinanceService.Lock(db,tenant);var settlement=await db.Set<InterEntitySettlement>().SingleOrDefaultAsync(x=>x.TenantId==tenant&&x.Id==id&&x.Status=="Pending Confirmation")??throw new AccessDeniedException();var x=await db.Set<InterEntityObligation>().SingleAsync(x=>x.Id==settlement.ObligationId&&x.TenantId==tenant);var from=await s.Require(tenant,x.EntityId,x.UnitId,"finance.interentity");var to=await s.Require(tenant,x.OtherEntityId,x.OtherUnitId,"finance.interentity");await a.Require(tenant,"finance.approve",x.OtherUnitId);await s.Review(tenant,id,settlement.AuthorId,x.UnitId!.Value,"FinanceSettlement",r,settlement.Amount,from);if(r.Decision=="Approve"){if(settlement.Amount>x.Amount-x.Settled)throw new DomainException("Settlement exceeds remaining obligation");var j=await s.Post(from,x.UnitId.Value,settlement.Date,"Confirmed bank settlement "+settlement.Reference,"InterEntitySettlement",id,"settlement:"+id,[new("2400",settlement.Amount,0),new("1010",0,settlement.Amount)],settlement.AuthorId,a.UserId);var other=await s.Post(to,x.OtherUnitId,settlement.Date,"Confirmed bank receipt "+settlement.Reference,"InterEntitySettlement",id,"settlement-received:"+id,[new("1010",settlement.Amount,0),new("1200",0,settlement.Amount)],settlement.AuthorId,a.UserId);settlement.JournalId=j.Id;settlement.OtherJournalId=other.Id;settlement.ApprovedBy=a.UserId;settlement.Status="Confirmed";x.Settled+=settlement.Amount;}else settlement.Status="Rejected";await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(settlement);});
 t.MapPost("/exchange-rates",async(Guid tenant,FinanceExchangeRate r,AppDb db,Access a,FinanceService s)=>{await s.Require(tenant,r.EntityId,r.UnitId,"finance.configure");if(!FinanceService.Currencies.ContainsKey(r.FromCurrency)||!FinanceService.Currencies.ContainsKey(r.ToCurrency)||r.FromCurrency==r.ToCurrency||r.Rate<=0||r.Rate>1000000000||r.Source.Length is <3 or >300)throw new DomainException("Supply two supported currencies, positive rate and its source");var rate=new FinanceExchangeRate{TenantId=tenant,EntityId=r.EntityId,UnitId=r.UnitId,Date=r.Date,FromCurrency=r.FromCurrency,ToCurrency=r.ToCurrency,Rate=r.Rate,Source=r.Source,AuthorId=a.UserId};db.Add(rate);a.Audit(tenant,"finance.exchange-rate.created",rate.Id);await db.SaveChangesAsync();return Results.Ok(rate);});
 }
}
public record ReverseWrite(DateOnly Date,string Reason);
public record SettlementWrite(decimal Amount,string Reference,DateOnly Date);
